def choose_move(observation):
    def sign(n):
        return 0 if n == 0 else (1 if n > 0 else -1)

    def first_pair(value):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            a, b = value[0], value[1]
            if isinstance(a, int) and isinstance(b, int):
                return [a, b]
        return None

    def get_pos(obs, keys, default=None):
        for k in keys:
            v = obs.get(k)
            p = first_pair(v)
            if p is not None:
                return p
        return default

    def move_toward(src, dst):
        if src is None or dst is None:
            return [0, 0]
        return [sign(dst[0] - src[0]), sign(dst[1] - src[1])]

    def best_by_manhattan(src, items, maximize=False):
        if not items:
            return None
        best_item = None
        best_score = None
        sx, sy = src
        for item in items:
            p = first_pair(item)
            if p is None:
                continue
            score = abs(p[0] - sx) + abs(p[1] - sy)
            if best_item is None or (maximize and score > best_score) or (not maximize and score < best_score):
                best_item = p
                best_score = score
        return best_item

    env = observation.get("environment_name", "") or ""
    sx, sy = get_pos(observation, ["self_position", "position", "agent_position"], [0, 0])
    ox, oy = get_pos(observation, ["opponent_position", "enemy_position", "target_position"], None)

    if env == "pursuit_evasion":
        role = observation.get("self_role", observation.get("role", "pursuer"))
        if role == "pursuer":
            if ox is not None:
                return move_toward([sx, sy], [ox, oy])
            target = get_pos(observation, ["prey_position"], None)
            if target is not None:
                return move_toward([sx, sy], target)
            return [0, 0]
        gw = observation.get("grid_width", observation.get("width", 0)) or 0
        gh = observation.get("grid_height", observation.get("height", 0)) or 0
        corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
