        for c in corners:
            if c[0] >= 0 and c[1] >= 0:
                valid.append(c)
        if ox is None:
            return [0, 0]
        target = best_by_manhattan([ox, oy], valid, maximize=True)
        return move_toward([sx, sy], target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells")
        if not targets:
            targets = observation.get("opponent_territory")
        if not targets:
            targets = observation.get("frontier_cells")
        target = best_by_manhattan([sx, sy], targets or [], maximize=False)
        if target is not None:
            return move_toward([sx, sy], target)
        if ox is not None:
            return move_toward([sx, sy], [ox, oy])
        return [0, 0]

    resources = observation.get("resources")
    if not resources:
        resources = observation.get("resource_positions")
    target = best_by_manhattan([sx, sy], resources or [], maximize=False)
    if target is not None:
        return move_toward([sx, sy], target)

    if ox is not None:
        return move_toward([sx, sy], [ox, oy])

